profit_X = num('W1::Unit profit', 'B38')
profit_Y = num('W1::Unit profit', 'B39')
res_rows = data_rows('W1::Resources', {'F': 'string', 'G': 'number', 'H': 'number', 'I': 'number'}, 708, 710)
constraints = []
for r in res_rows:
    cap = num('W1::Resources', f'G{r}')
    y_coeff = num('W1::Resources', f'H{r}')
    x_coeff = num('W1::Resources', f'I{r}')
    constraints.append((x_coeff, y_coeff, cap))

# Solve LP with 2 variables X >= 0, Y >= 0
# Vertices are intersections of constraints with axes and each other
points = [(0.0, 0.0)]
for x_c, y_c, cap in constraints:
    if x_c != 0:
        points.append((cap / x_c, 0.0))
    if y_c != 0:
        points.append((0.0, cap / y_c))

for i in range(len(constraints)):
    for j in range(i + 1, len(constraints)):
        a1, b1, c1 = constraints[i]
        a2, b2, c2 = constraints[j]
        det = a1 * b2 - a2 * b1
        if det != 0:
            x = (c1 * b2 - c2 * b1) / det
            y = (a1 * c2 - a2 * c1) / det
            if x >= -1e-7 and y >= -1e-7:
                points.append((max(0.0, x), max(0.0, y)))

max_p = 0.0
for x, y in points:
    feasible = True
    for x_c, y_c, cap in constraints:
        if x_c * x + y_c * y > cap + 1e-7:
            feasible = False
            break
    if feasible:
        p = profit_X * x + profit_Y * y
        if p > max_p:
            max_p = p

result = round(max_p, 2)

